def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    own = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')
    opp_coop = n - opp_def
    last_opp = opp[-1]
    last_own = own[-1]

    # Forgiving, optimistic opening
    if n < 3:
        return 'C'

    # If opponent has never defected, cooperate
    if opp_def == 0:
        return 'C'

    # If opponent defected only once, likely noise or a test; forgive once
    if opp_def == 1 and opp_coop >= 2:
        # If it was the last move, forgive
        if last_opp == 'D':
            return 'C'
        return 'C'

    # Detect runs of defection
    run_def = 0
    for a in reversed(opp):
        if a == 'D':
            run_def += 1
        else:
            break

    run_coop = 0
    for a in reversed(opp):
        if a == 'C':
            run_coop += 1
        else:
            break

    # Very recent sustained defection: retaliate
    if run_def >= 3:
        return 'D'

    # If opponent defected last but not sustained, use a mostly-forgiving tit-for-tat
    if last_opp == 'D':
        # If we just defected last (already retaliated), and opponent now cooperated, return to C
        if last_own == 'D':
            return 'C' if run_coop >= 1 else 'D'
        # Otherwise, retaliate but not permanently
        return 'D'

    # Opponent cooperated last
    if last_own == 'D':
        # We were retaliating; now return to cooperation
        return 'C'

    # Default cooperate, unless opponent has a high defection rate
    # Threshold: if more than 40% defection, be cautious
    if opp_def * 5 > n * 2:
        # Defect more often to avoid being exploited
        return 'D' if rng.random() < 0.7 else 'C'

    # Otherwise cooperate with occasional random defection to test
    if n % 17 == 0 and rng.random() < 0.1:
        return 'D'

    return 'C'

